    it("WRAPPER_RULES equals WRAPPER_TABLE: every wrapper, its option table and its positionals, in order", () => {
      expect(WRAPPER_RULES.map(([id, rule]) => ({ id, arguments: [...rule.arguments], positionals: rule.positionals, commands: [...rule.commands] }))).toStrictEqual(WRAPPER_TABLE);
    });
    it("every member of every planted roster, every wrapper and every wrapper option has its own R: plant", () => {
      const owed = [
        ...ROSTERS.filter(row => PLANTED_ROSTERS.includes(row.id)).flatMap(row => row.members.map(member => `R:${row.id}:${member}`)),
        ...WRAPPER_TABLE.flatMap(row => [`R:WRAPPER:${row.id}`, ...row.arguments.map(option => `R:WRAPPER-ARG:${row.id} ${option}`), ...row.commands.map(option => `R:WRAPPER-CMD:${row.id} ${option}`)]),
      ];
      const planted = SUB_READINGS.map(row => row.id).filter(id => id.startsWith("R:") && !id.startsWith("R:COMMAND_SEPARATOR:"));
      expect(planted.sort()).toStrictEqual(owed.sort());
    });
